import { expect, type Page } from "@playwright/test";

import { LLM_TIMEOUT } from "@e2e/config";

export const getLocators = (page: Page) => {
  const chat = page.getByTestId("assistant-chat");
  // Match only non–last-active events. The last active event uses
  // `conversation-events-last-active-event` and often duplicates labels such as
  // "Waiting for user input" (action_listen) already shown earlier in the log.
  const conversationEvents = chat.getByTestId("conversation-events");

  return {
    chat,
    conversationEvents,
    conversationEvent: (eventName: string) =>
      conversationEvents.getByText(eventName, { exact: true }).first(),
    conversationEventRow: (eventName: string) => conversationEvents.filter({ hasText: eventName }),
    agentTurnEndedEvents: chat.getByText("Agent turn ended", { exact: true }),
    loadingDots: chat.getByTestId("loading-dots"),
    sessionBanner: chat.getByText(/Session started on/),
    userMessages: chat.getByTestId("assistant-user-message"),
    botMessages: chat.getByTestId("assistant-response"),
    botButton: (label: string) => chat.getByRole("button", { name: label, exact: true }),
    botImage: chat.getByTestId("assistant-response").locator("img"),
    // A tool-call row only renders this toggle when it has nested memory writes.
    toolCallToggles: chat.getByTestId("tool-call-toggle"),
    // The nested-writes box is present in the DOM only while the group is expanded.
    toolCallGroups: chat.getByTestId("tool-call-group"),
  };
};

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    // Requires Inspect mode: conversation events (including "Agent turn ended")
    // are not rendered in Preview.
    completeTurn: async (startTurn: () => Promise<void>) => {
      const turnsEndedBefore = await locators.agentTurnEndedEvents.count();
      await startTurn();
      await expect(
        locators.agentTurnEndedEvents.nth(turnsEndedBefore),
        "Agent turn should end before the next step runs",
      ).toBeVisible({ timeout: LLM_TIMEOUT });
    },
    clickConversationEvent: async (eventName: string) => {
      await locators.conversationEvent(eventName).click();
    },
    clickBotMessage: async (index = 0) => {
      await locators.botMessages.nth(index).click();
    },
    clickUserMessage: async (index = 0) => {
      await locators.userMessages.nth(index).click();
    },
    clickBotButton: async (label: string) => {
      const button = locators.botButton(label);
      await expect(button, `Bot button "${label}" should be enabled before click`).toBeEnabled({
        timeout: LLM_TIMEOUT,
      });
      await button.click();
    },
    focusConversationEvent: async (eventName: string) => {
      await locators.conversationEvent(eventName).focus();
    },
    pressEnterOnFocusedEvent: async () => {
      await page.keyboard.press("Enter");
    },
    expandFirstToolCall: async () => {
      await locators.toolCallToggles.first().click();
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    userMessageIsVisible: async (message: string) => {
      await expect(
        locators.userMessages.filter({ hasText: message }),
        `User message "${message}" should appear in chat`,
      ).toBeVisible();
    },
    userMessageCountIs: async (count: number) => {
      await expect(locators.userMessages, `User message count should be ${count}`).toHaveCount(
        count,
      );
    },
    botMessageCountIs: async (count: number) => {
      await expect(locators.botMessages, `Bot message count should be ${count}`).toHaveCount(count);
    },
    botMessageCountReached: async (count: number, timeout = LLM_TIMEOUT) => {
      await expect(locators.botMessages, `Bot message count should reach ${count}`).toHaveCount(
        count,
        { timeout },
      );
    },
    botMessageCountAtLeast: async (minCount: number, timeout = LLM_TIMEOUT) => {
      await expect(
        locators.botMessages.nth(minCount - 1),
        `Bot message count should be at least ${minCount}`,
      ).toBeVisible({ timeout });
    },
    agentTurnEndedCountAtLeast: async (minCount: number, timeout = LLM_TIMEOUT) => {
      await expect(
        locators.agentTurnEndedEvents.nth(minCount - 1),
        `Agent turn ended count should be at least ${minCount}`,
      ).toBeVisible({ timeout });
    },
    conversationEventIsVisible: async (eventName: string) => {
      await expect(
        locators.conversationEvent(eventName),
        `Conversation event "${eventName}" should be visible`,
      ).toBeVisible({ timeout: LLM_TIMEOUT });
    },
    conversationEventReached: async (eventName: string) => {
      await expect(
        locators.conversationEvent(eventName),
        `Conversation event "${eventName}" should appear in log`,
      ).toBeVisible({ timeout: LLM_TIMEOUT });
    },
    errorDotOnEventIsVisible: async (eventName: string) => {
      await expect(
        locators.conversationEventRow(eventName).getByTestId("error-dot"),
        `Error dot should be visible on "${eventName}" event`,
      ).toBeVisible();
    },
    loadingDotsVisible: async () => {
      await expect(
        locators.loadingDots,
        "Loading dots should be visible while waiting for bot response",
      ).toBeVisible();
    },
    loadingDotsHidden: async () => {
      await expect(
        locators.loadingDots,
        "Loading dots should be hidden after bot response",
      ).toBeHidden();
    },
    sessionBannerIsVisible: async () => {
      await expect(
        locators.sessionBanner,
        "Session started banner should be visible",
      ).toBeVisible();
    },
    botImageIsVisible: async () => {
      await expect(locators.botImage, "Bot message image should be visible").toBeVisible();
    },
    toolCallToggleCountAtLeast: async (count: number, timeout = LLM_TIMEOUT) => {
      await expect
        .poll(async () => await locators.toolCallToggles.count(), {
          message: `At least ${count} collapsible tool-call row(s) should be in the log`,
          timeout,
        })
        .toBeGreaterThanOrEqual(count);
    },
    toolCallGroupIsVisible: async () => {
      await expect(
        locators.toolCallGroups.first(),
        "An expanded tool-call group (its nested memory writes) should be visible",
      ).toBeVisible();
    },
    lifecycleRowIsVisible: async (text: string) => {
      await expect(
        locators.conversationEvents.getByText(text).first(),
        `Conversation log should show a "${text}" row`,
      ).toBeVisible({ timeout: LLM_TIMEOUT });
    },
  };
};
